/// Everything here is owned/synthetic: generated bytes, scratch directories, fake transports, an in-memory sink or an
/// isolated test keychain. Nothing touches a real store, account, Keychain item or network.
final class ManualWall: WallClock, Sendable {
    let value = Mutex(Date(timeIntervalSince1970: 1_800_000_000))
    func now() -> Date { value.withLock { $0 } }
    func advance(_ seconds: TimeInterval) { value.withLock { $0 = $0.addingTimeInterval(seconds) } }
}
final class FakeVolume: VolumeCapacityProviding, Sendable {
    let state = Mutex(VolumeCapacity(total: 1000 * DownloadPolicy.gibibyte, available: 500 * DownloadPolicy.gibibyte))
    func capacity(at url: URL) -> VolumeCapacity { state.withLock { $0 } }
    func set(total: Int64? = nil, available: Int64? = nil) { state.withLock { if let total { $0.total = total }; if let available { $0.available = available } } }
}
final class WakeRecorder: Sendable {
    let dates = Mutex<[Date]>([])
    var scheduler: DownloadScheduler.WakeScheduler { { [self] date, _ in dates.withLock { $0.append(date) }; return {} } }
}

func payload(_ count: Int, seed: UInt8 = 7) -> Data {
    var state = UInt64(seed) &* 0x9E3779B97F4A7C15 | 1
    return Data((0..<count).map { _ in state ^= state << 13; state ^= state >> 7; state ^= state << 17; return UInt8(truncatingIfNeeded: state) })
}
func sha(_ data: Data) -> String { SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined() }
func owned(_ name: String) -> ServiceID { try! ServiceID("owned-" + name) }
func youtube(_ name: String) -> ServiceID { try! ServiceID(name) }

/// A scripted source: serves generated bytes, can expire its address, change variant, serve corrupt bytes, fail, or block
/// a read until released so tests can stop a job in the middle of a transfer.
actor FakeSource: DownloadSource {
    struct Script {
        var bytes: Data
        var variant = "variant-1"
        var validator: String? = "v1"
        var length: Int64?
        var supportsRanges = true
        var publishedSHA256: String?
        var servedBytes: Data?                 // what is actually served when it differs from `bytes` (corruption)
        var permissionLifetime: TimeInterval = 3600
        var renewAfter: TimeInterval? = nil
        /// The source can state the digest of what it really holds (like a local file), without publishing one up front.
        var digestFromSource = false
    }
    private(set) var scripts: [String: Script] = [:]
    private(set) var reads: [(media: String, variant: String, offset: Int64, count: Int)] = []
    private(set) var describes = 0
    private var failuresByRead: [Int: SourceFailure] = [:]
    private var readCount = 0
    private var holdAfterReads: Int?
    private var heldContinuation: [UUID: CheckedContinuation<Void, Never>] = [:]
    private var blocked = 0
    private var ignoreCancellation = false
    private var renewalError: SourceFailure?
    private var describeError: SourceFailure?
    private let wall: any WallClock
    init(wall: any WallClock) { self.wall = wall }

    func set(_ media: ServiceID, _ script: Script) { var copy = script; if copy.length == nil { copy.length = Int64(script.bytes.count) }; scripts[media.rawValue] = copy }
    func setUnknownLength(_ media: ServiceID, bytes: Data, supportsRanges: Bool = true) { scripts[media.rawValue] = Script(bytes: bytes, length: -1, supportsRanges: supportsRanges) }
    func update(_ media: ServiceID, _ change: (inout Script) -> Void) { change(&scripts[media.rawValue]!) }
    func failRead(number: Int, with failure: SourceFailure) { failuresByRead[number] = failure }
    func clearFailures() { failuresByRead = [:] }
    func failEveryRead(with failure: SourceFailure) { for n in 1...500 { failuresByRead[n] = failure } }
    func holdAfter(reads count: Int?) { holdAfterReads = count }
    func ignoreCancellationWhileHeld(_ value: Bool) { ignoreCancellation = value }
    func failDescribe(_ failure: SourceFailure?) { describeError = failure }
    func failRenewal(_ failure: SourceFailure?) { renewalError = failure }
    func release() { holdAfterReads = nil; let waiting = heldContinuation; heldContinuation = [:]; for c in waiting.values { c.resume() } }
    private func wake(_ id: UUID) { heldContinuation.removeValue(forKey: id)?.resume() }
    /// Bounded: a scenario that never reaches the held read fails the test instead of hanging the run.
    func waitUntilBlocked(timeout: Duration = .seconds(5), file: StaticString = #filePath, line: UInt = #line) async {
        let deadline = ContinuousClock.now + timeout
        while blocked == 0 { guard ContinuousClock.now < deadline else { XCTFail("no read reached the held source within \(timeout)", file: file, line: line); return }; try? await Task.sleep(for: .milliseconds(2)) }
    }
    var blockedCount: Int { blocked }
    var readLog: [(media: String, variant: String, offset: Int64, count: Int)] { reads }

    func describe(item: SourceItem, context: RequestContext) async throws -> SourceDescriptor {
        describes += 1
        if let describeError { throw describeError }
        guard let script = scripts[item.media.rawValue] else { throw SourceFailure.unavailable }
        let length: Int64? = script.length == -1 ? nil : script.length
        let now = wall.now()
        let permission = DownloadPermission(issuer: "Owned synthetic test license", sourceEncryption: "none: synthetic", validatedAt: now, expires: now.addingTimeInterval(script.permissionLifetime),
                                            renewAfter: script.renewAfter.map { now.addingTimeInterval($0) }, renewalReference: "synthetic-renewal")
        return SourceDescriptor(variant: script.variant, validator: script.validator, length: length, supportsRanges: script.supportsRanges, urlExpiresAt: now.addingTimeInterval(60), sha256: script.publishedSHA256, permission: permission)
    }
    func read(item: SourceItem, descriptor: SourceDescriptor, offset: Int64, count: Int, context: RequestContext) async throws -> SourceRead {
        readCount += 1
        let number = readCount
        if let holdAfterReads, number > holdAfterReads {
            blocked += 1
            let id = UUID()
            if ignoreCancellation { await withCheckedContinuation { heldContinuation[id] = $0 } }
            else { await withTaskCancellationHandler { await withCheckedContinuation { heldContinuation[id] = $0 } } onCancel: { Task { await self.wake(id) } } }
            blocked -= 1
            if !ignoreCancellation { try Task.checkCancellation() }
        }
        if let failure = failuresByRead[number] { failuresByRead[number] = nil; throw failure }
        guard let script = scripts[item.media.rawValue] else { throw SourceFailure.unavailable }
        if script.variant != descriptor.variant || script.validator != descriptor.validator { throw SourceFailure.urlExpired }
        reads.append((item.media.rawValue, descriptor.variant, offset, count))
        let served = script.servedBytes ?? script.bytes
        guard offset < Int64(served.count) else { return SourceRead(data: Data(), endOfStream: true) }
        let end = min(Int(offset) + count, served.count)
        return SourceRead(data: served.subdata(in: Int(offset)..<end), endOfStream: end >= served.count)
    }
    func contentDigest(item: SourceItem, descriptor: SourceDescriptor, length: Int64) async throws -> String? {
        guard let script = scripts[item.media.rawValue], script.digestFromSource else { return nil }
        return sha(script.bytes.prefix(Int(length)))
    }
    func renew(item: SourceItem, descriptor: SourceDescriptor, context: RequestContext) async throws -> DownloadPermission {
        if let renewalError { throw renewalError }
        let now = wall.now()
        return DownloadPermission(issuer: "Owned synthetic test license", sourceEncryption: "none: synthetic", validatedAt: now, expires: now.addingTimeInterval(7200), renewAfter: now.addingTimeInterval(3600), renewalReference: "synthetic-renewal")
    }
}

/// In-memory stand-in for the W14 store, honouring the same reference-counting contract (an object with no references and
/// no pin is deleted). Used where speed matters; the real encrypted store is exercised separately.
actor MemorySink: RetentionSink {
    struct Object { var bytes: Data; var references: Set<String>; var pinned: Bool; var grant: RetentionGrant }
    private(set) var objects: [String: Object] = [:]
    private(set) var retainCalls = 0
    private(set) var boundContext: RequestContext?
    var retainError: Error?
    var lengthError: Error?
    var verifyError: Error?
    func setRetainError(_ error: Error?) { retainError = error }
    func setLengthError(_ error: Error?) { lengthError = error }
    func setVerifyError(_ error: Error?) { verifyError = error }
    func retain(file: URL, variant: String, grant: RetentionGrant, reference: String, context: RequestContext) async throws {
        retainCalls += 1
        if let retainError { throw retainError }
        if objects[variant] != nil { objects[variant]!.references.insert(reference); return }
        objects[variant] = Object(bytes: try Data(contentsOf: file), references: [reference], pinned: false, grant: grant)
    }
    func addReference(variant: String, reference: String, context: RequestContext) async throws {
        guard objects[variant] != nil else { throw OfflineRecovery.notRetained }; objects[variant]!.references.insert(reference)
    }
    func removeReference(variant: String, reference: String, context: RequestContext) async throws {
        guard objects[variant] != nil else { return }
        objects[variant]!.references.remove(reference)
        if objects[variant]!.references.isEmpty && !objects[variant]!.pinned { objects[variant] = nil }
    }
    func setPinned(variant: String, pinned: Bool, context: RequestContext) async throws {
        guard objects[variant] != nil else { throw OfflineRecovery.notRetained }
        objects[variant]!.pinned = pinned
        if objects[variant]!.references.isEmpty && !pinned { objects[variant] = nil }
    }
    func retainedLength(variant: String, context: RequestContext) async throws -> Int {
        if let lengthError { throw lengthError }
        guard let object = objects[variant] else { throw OfflineRecovery.notRetained }; return object.bytes.count
    }
    func verify(variant: String, context: RequestContext) async throws -> String? {
        if let verifyError { throw verifyError }
        guard let object = objects[variant] else { throw OfflineRecovery.notRetained }
        return sha(object.bytes)
    }
    func updateGrant(variant: String, grant: RetentionGrant, context: RequestContext) async throws {
        guard objects[variant] != nil else { throw OfflineRecovery.notRetained }; objects[variant]!.grant = grant
    }
    func delete(variant: String, context: RequestContext) async throws { objects[variant] = nil }
    func bind(_ context: RequestContext) async { boundContext = context }
    func has(_ variant: String) -> Bool { objects[variant] != nil }
    func bytes(_ variant: String) -> Data? { objects[variant]?.bytes }
    func references(_ variant: String) -> Set<String>? { objects[variant]?.references }
    func isPinned(_ variant: String) -> Bool? { objects[variant]?.pinned }
    func grant(_ variant: String) -> RetentionGrant? { objects[variant]?.grant }
    var count: Int { objects.count }
}

struct Env {
    let root: URL
    let manual = ManualWall()
    /// The manual clock, or the system clock when a real encrypted store (whose own clock is the system's) is involved.
    let wall: any WallClock
    let volume = FakeVolume()
    let account: AccountContext
    let context: RequestContext
    let otherAccount: AccountContext
    var ledgerURL: URL { root.appendingPathComponent("jobs", isDirectory: true) }
    var objectsURL: URL { root.appendingPathComponent("objects", isDirectory: true) }
    init(systemClock: Bool = false) throws {
        wall = systemClock ? SystemWallClock() : manual
        root = FileManager.default.temporaryDirectory.appendingPathComponent("W15-" + UUID().uuidString, isDirectory: true)
        try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
        account = try AccountContext(accountID: UUID(), channelID: ID("w15-channel-a"), region: "US")
        otherAccount = try AccountContext(accountID: UUID(), channelID: ID("w15-channel-b"), region: "US")
        context = RequestContext(account: account, accountGeneration: 1, requestGeneration: 0)
    }
    func context(for account: AccountContext, generation: UInt64 = 1) -> RequestContext { RequestContext(account: account, accountGeneration: generation, requestGeneration: 0) }
    func cleanup() { try? FileManager.default.removeItem(at: root) }
    func makeScheduler(source: FakeSource, sink: any RetentionSink, configuration: DownloadScheduler.Configuration = .init(chunkBytes: 1024, persistEveryChunks: 1, minimumBudget: 1024),
                       network: (any NetworkPathProviding)? = nil, power: (any PowerStateProviding)? = nil, wake: DownloadScheduler.WakeScheduler? = nil,
                       checkpoint: (@Sendable (SchedulerCheckpoint) throws -> Void)? = nil, random: @escaping @Sendable () -> Double = { 0.5 }) throws -> DownloadScheduler {
        try DownloadScheduler(ledgerRoot: ledgerURL, sink: sink, sources: [.owned: source, .localFile: source, .publisherGrant: source], wall: wall, network: network, power: power, volume: volume,
                              configuration: configuration, random: random, wake: wake ?? WakeRecorder().scheduler, checkpoint: checkpoint, suggestionsAvailable: true,
                              originOf: { $0.rawValue.hasPrefix("owned-") ? .owned : MediaOrigin.classify($0) })
    }
    /// An isolated test keychain and a real W14 encrypted store beside the ledger.
    func realStore() throws -> (store: EncryptedStore, vault: KeychainVault, sink: EncryptedStoreSink) {
        let vault = try KeychainVault(testNamespace: KeychainVault.applicationNamespace + ".test." + UUID().uuidString, isolatedKeychainURL: root.appendingPathComponent("test.keychain-db"))
        let store = try EncryptedStore(root: objectsURL, vault: vault)
        return (store, vault, EncryptedStoreSink(store: store))
    }
    func stagingFiles(for account: AccountContext? = nil) -> [String] {
        let dir = ledgerURL.appendingPathComponent(DownloadLedgerNames.directory(account ?? self.account)).appendingPathComponent("staging")
        return (try? FileManager.default.contentsOfDirectory(atPath: dir.path)) ?? []
    }
}
enum DownloadLedgerNames {
    static func directory(_ account: AccountContext) -> String {
        let framed = account.accountID.uuidString + ":\(account.channelID.rawValue.utf8.count):" + account.channelID.rawValue + ":" + account.region
        return SHA256.hash(data: Data(framed.utf8)).map { String(format: "%02x", $0) }.joined()
    }
}
final class FakeNetwork: NetworkPathProviding, Sendable {
    let state = Mutex(NetworkPathState())
    func current() -> NetworkPathState { state.withLock { $0 } }
    func observe(_ change: @escaping @Sendable (NetworkPathState) -> Void) -> @Sendable () -> Void { {} }
}
final class FakePower: PowerStateProviding, Sendable {
    let low = Mutex(false)
    func lowPowerMode() -> Bool { low.withLock { $0 } }
    func observe(_ change: @escaping @Sendable (Bool) -> Void) -> @Sendable () -> Void { {} }
}

extension DownloadScheduler {
    /// `settle`, but a job that never stops fails the test instead of hanging the run (a changed guard then reads as a failure).
    func settleBounded(file: StaticString = #filePath, line: UInt = #line) async {
        let stopped = await settle(timeout: .seconds(20))
        XCTAssertTrue(stopped, "a job was still running after 20 s", file: file, line: line)
    }
    func onlyRow() throws -> DownloadRowModel {
        let rows = snapshot().rows
        guard rows.count == 1, let row = rows.first else { throw NSError(domain: "DownloadsTests", code: rows.count, userInfo: [NSLocalizedDescriptionKey: "expected exactly one row, found \(rows.count)"]) }
        return row
    }
    func row(_ media: ServiceID) -> DownloadRowModel? { snapshot().rows.first { $0.media == media } }
    /// Waits (bounded) until `condition` holds for the snapshot, driving `settle` between looks.
    func waitFor(_ description: String, timeout: Duration = .seconds(10), _ condition: @Sendable (DownloadsSnapshot) -> Bool) async -> Bool {
        let deadline = ContinuousClock.now + timeout
        while ContinuousClock.now < deadline {
            if condition(snapshot()) { return true }
            try? await Task.sleep(for: .milliseconds(5))
        }
        return condition(snapshot())
    }
}
